const avatarClass={MA:'avatar-blue',QH:'avatar-purple',TT:'avatar-green',HN:'avatar-orange'};
function avatar(code){return `<span class="avatar ${avatarClass[code]||'avatar-blue'}">${code}</span>`}
function priorityClass(p){return p==='Khẩn cấp'?'p-urgent':p==='Cao'?'p-high':p==='Thấp'?'p-low':'p-medium'}
function pageHead(kicker,title,desc,actions=''){return `<div class="page-head"><div><p class="eyebrow">${kicker}</p><h1>${title}</h1><p>${desc}</p></div><div class="head-actions">${actions}</div></div>`}
function dashboard(){
 const total=tasks.length,completed=tasks.filter(t=>t.status==='Hoàn thành').length,nearDue=tasks.filter(t=>t.status!=='Hoàn thành'&&t.progress>=70).length,overdue=tasks.filter(t=>t.due.includes('Quá')).length,rate=total?Math.round(completed/total*100):0;
 const rows=tasks.slice(0,5).map(t=>`<tr><td><div class="task-title"><input type="checkbox" ${t.status==='Hoàn thành'?'checked':''}><div>${t.title}<div class="project-name">${t.project}</div></div></div></td><td><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></td><td><div class="progress"><i style="width:${t.progress}%"></i></div></td><td class="due ${t.due.includes('Quá')?'overdue':''}">${t.due}</td><td>${avatar(t.assignee)}</td></tr>`).join('');
 const bars=[['45','38'],['60','52'],['72','66'],['58','73'],['82','76'],['88','84'],['91','87']].map((b,i)=>`<div class="bar-pair"><i class="bar" style="height:${b[0]}%"></i><i class="bar actual" style="height:${b[1]}%"></i><small>T${i+5}</small></div>`).join('');
 const resultPerson=people[0];
 return `${pageHead('THỨ BA, 10 THÁNG 11','Chào buổi sáng, Quản trị GR','Đây là những điều cần bạn chú ý hôm nay.','<button class="filter-btn">◫ Tuần này</button><button class="filter-btn">⇩ Xuất báo cáo</button>')}
 <div class="kpi-grid"><div class="kpi-card"><div class="kpi-top"><span>Tổng công việc</span><i class="metric-icon">✓</i></div><div class="kpi-value">${total}</div><div class="delta">Dữ liệu trực tiếp từ module Công việc</div></div><div class="kpi-card"><div class="kpi-top"><span>Hoàn thành</span><i class="metric-icon green">↗</i></div><div class="kpi-value">${completed}</div><div class="delta"><b>${rate}%</b> tỷ lệ hoàn thành</div></div><div class="kpi-card"><div class="kpi-top"><span>Sắp đến hạn</span><i class="metric-icon amber">◷</i></div><div class="kpi-value">${nearDue}</div><div class="delta">Tiến độ từ 70% chưa hoàn thành</div></div><div class="kpi-card"><div class="kpi-top"><span>Quá hạn</span><i class="metric-icon red">!</i></div><div class="kpi-value">${overdue}</div><div class="delta down">Cần xử lý ngay</div></div></div>
 <div class="card employee-results"><div class="card-head"><div><h2>Kết quả thực hiện theo nhân viên</h2><p>Chọn nhân viên để xem khối lượng, hoàn thành, đúng hạn và KPI</p></div><div class="employee-result-picker">${people.map((p,i)=>`<button class="member-chip ${i===0?'active':''}" data-result-person="${p.code}">${avatar(p.initials)} ${p.name}</button>`).join('')}</div></div><div id="employeeResultChart">${employeeResultChart(resultPerson)}</div></div>
 <div class="dashboard-grid"><div class="stack"><div class="card"><div class="card-head"><div><h2>Tiến độ công việc</h2><p>Kế hoạch so với thực tế trong 7 tháng</p></div><button class="text-btn">Xem báo cáo →</button></div><div class="chart-wrap"><div class="chart">${bars}</div><div class="legend"><span><i style="background:#b2ccff"></i>Kế hoạch</span><span><i style="background:#155eef"></i>Thực tế</span></div></div></div><div class="card"><div class="card-head"><div><h2>Công việc ưu tiên</h2><p>Tập trung xử lý trước khi kết thúc ngày</p></div><button class="text-btn" data-go="mytasks">Xem tất cả</button></div><div style="overflow:auto"><table class="task-table"><thead><tr><th>CÔNG VIỆC</th><th>ƯU TIÊN</th><th>TIẾN ĐỘ</th><th>HẠN</th><th>PHỤ TRÁCH</th></tr></thead><tbody>${rows}</tbody></table></div></div></div>
 <div class="stack"><div class="card"><div class="card-head"><div><h2>Cảnh báo cần xử lý</h2><p>4 vấn đề ảnh hưởng tiến độ</p></div><span class="badge">Realtime</span></div><div><div class="alert-item"><i class="alert-dot"></i><div><b>2 công việc đã quá hạn</b><p>Dự án ERP Transformation</p></div><span class="badge">Critical</span></div><div class="alert-item"><i class="alert-dot amber"></i><div><b>Nhân sự 01 đang quá tải</b><p>128% năng lực tuần này</p></div><span class="badge">Warning</span></div><div class="alert-item"><i class="alert-dot amber"></i><div><b>Milestone có nguy cơ trễ</b><p>Website 2026 · 3 ngày</p></div><span class="badge">AI</span></div></div></div><div class="card"><div class="card-head"><div><h2>Hoạt động gần đây</h2><p>Cập nhật từ đội dự án</p></div></div><div class="activity-list"><div class="activity">${avatar('MA')}<div><p><b>Nhân sự 01</b> đã gửi duyệt TSK-1038</p><time>12 phút trước</time></div></div><div class="activity">${avatar('QH')}<div><p><b>Nhân sự 02</b> bình luận trong ERP</p><time>34 phút trước</time></div></div><div class="activity">${avatar('TT')}<div><p><b>Nhân sự 03</b> hoàn thành 3 checklist</p><time>1 giờ trước</time></div></div><div class="activity">${avatar('HN')}<div><p><b>Nhân sự 04</b> cập nhật tiến độ 80%</p><time>2 giờ trước</time></div></div></div></div></div></div>`
}
function employeeResultChart(p){const own=tasks.filter(t=>t.assignee===p.initials),completion=own.length?Math.round(own.reduce((s,t)=>s+t.progress,0)/own.length):0,overdue=own.filter(t=>t.due.includes('Quá')).length,onTime=own.length?Math.round((own.length-overdue)/own.length*100):100;const stats=[['Khối lượng',Math.min(p.workload,100),'#155eef'],['Hoàn thành',completion,'#079455'],['Đúng hạn',onTime,'#dc6803'],['KPI',p.kpi,'#6941c6']];return `<div class="employee-result-chart"><div class="result-profile">${avatar(p.initials)}<div><b>${p.name}</b><span>${p.position} · ${own.length} công việc</span></div><strong>${p.kpi}<small>KPI</small></strong></div><div class="result-bars">${stats.map(s=>`<div><span>${s[0]}</span><div><i style="width:${s[1]}%;background:${s[2]}"></i></div><b>${s[1]}%</b></div>`).join('')}</div></div>`}
function taskCard(t){return `<article class="task-card" draggable="true" data-id="${t.id}"><div class="task-card-head"><span class="code">${t.id} · ${t.project}</span><button class="task-delete" data-delete-task="${t.id}" title="Xóa công việc">×</button></div><h3>${t.title}</h3><div class="tags"><span class="priority ${priorityClass(t.priority)}">${t.priority}</span></div><footer><span>◷ ${t.due}</span><span class="avatar-stack">${avatar(t.assignee)}</span></footer></article>`}
function myTasks(){return `${pageHead('QUẢN LÝ CÔNG VIỆC','Công việc','Kéo thả thẻ để cập nhật trạng thái hoặc xóa công việc không còn sử dụng.','<button class="filter-btn">☷ Bộ lọc</button><button class="filter-btn">↕ Sắp xếp</button>')}<div class="toolbar"><div class="view-tabs"><button class="tab active">▦ Bảng</button><button class="tab">☷ Danh sách</button><button class="tab">▣ Lịch</button><button class="tab">⌁ Gantt</button></div><span class="project-name">Hiển thị ${tasks.length} công việc</span></div><div class="kanban">${statusOrder.map(s=>`<section class="kanban-col" data-status="${s}"><div class="kanban-head">${s}<span>${tasks.filter(t=>t.status===s).length}</span></div>${tasks.filter(t=>t.status===s).map(taskCard).join('')}</section>`).join('')}</div>`}
function teamCalendar(){const memberMap=Object.fromEntries(people.map(p=>[p.initials,p.name]));const days=[['Thứ hai','09/11'],['Thứ ba','10/11'],['Thứ tư','11/11'],['Thứ năm','12/11'],['Thứ sáu','13/11'],['Thứ bảy','14/11'],['Chủ nhật','15/11']];return `${pageHead('LỊCH CÔNG VIỆC NHÓM','Lịch công việc toàn bộ thành viên','Dữ liệu nhân sự lấy trực tiếp từ Nhân sự phòng ban.','<button class="filter-btn">‹</button><button class="filter-btn">09 – 15/11/2026</button><button class="filter-btn">›</button><button class="primary-btn" id="calendarNewTask">＋ Công việc</button>')}<div class="calendar-toolbar"><div class="view-tabs"><button class="tab">Ngày</button><button class="tab active">Tuần</button><button class="tab">Tháng</button></div><div class="member-filters"><button class="member-chip active" data-member-filter="all">Tất cả</button>${Object.entries(memberMap).map(([k,v])=>`<button class="member-chip" data-member-filter="${k}">${avatar(k)} ${v}</button>`).join('')}</div></div><div class="team-calendar"><div class="calendar-time-head">GMT+7</div>${days.map((d,i)=>`<div class="calendar-day-head ${i===1?'today':''}"><b>${d[0]}</b><span>${d[1]}</span></div>`).join('')}<div class="time-scale">${['08:00','10:00','12:00','14:00','16:00','18:00'].map(x=>`<span>${x}</span>`).join('')}</div>${days.map((d,dayIndex)=>`<div class="calendar-day">${tasks.filter((_,i)=>i%7===dayIndex).map((t,i)=>`<article class="calendar-task ${priorityClass(t.priority)}" data-calendar-member="${t.assignee}" style="top:${18+i*72}px;height:${54+(t.progress%2)*16}px"><b>${t.title}</b><span>${memberMap[t.assignee]||'Chưa phân công'} · ${t.project}</span><footer>${avatar(t.assignee)} <em>${t.progress}%</em></footer></article>`).join('')}</div>`).join('')}</div><div class="calendar-summary"><span><b>${tasks.length}</b> công việc</span><span><b>${people.length}</b> thành viên</span><span><b>${tasks.filter(t=>t.progress>=70&&t.status!=='Hoàn thành').length}</b> gần hoàn thành</span><span class="danger-text"><b>${tasks.filter(t=>t.due.includes('Quá')).length}</b> quá hạn</span></div>`}
function projects(){return `${pageHead('DANH MỤC DỰ ÁN','Tất cả dự án','Theo dõi sức khỏe, tiến độ và rủi ro của danh mục.','<button class="filter-btn">☷ Bộ lọc</button><button class="primary-btn" data-add-project>＋ Dự án mới</button>')}<div class="project-grid">${projectRecords.map(p=>`<article class="card project-card" data-project-code="${p.code}"><header><span class="project-icon">${p.name.split(' ').map(x=>x[0]).join('').slice(0,3)}</span><div class="project-card-actions"><span class="priority ${p.progress>75?'p-low':p.progress<40?'p-high':'p-medium'}">${p.progress>75?'Đúng tiến độ':p.progress<40?'Có rủi ro':'Theo dõi'}</span><button class="text-btn" data-edit-project="${p.code}">Sửa</button><button class="delete-icon" data-delete-project="${p.code}" title="Xóa dự án">×</button></div></header><h3>${p.name}</h3><p>${p.desc}</p><div class="project-owner"><span>${p.code} · ${p.type}</span><b>${p.manager}</b></div><div class="project-meta"><span>${p.start||'Chưa có ngày bắt đầu'} → ${p.due}</span><b>${p.progress}%</b></div><div class="progress"><i style="width:${p.progress}%"></i></div><div class="mini-stats"><div><b>${p.due}</b><small>HOÀN THÀNH</small></div><div><b>${Array.isArray(p.assignees)?p.assignees.length:p.members}</b><small>THÀNH VIÊN</small></div><div><b>${p.alerts}</b><small>CẢNH BÁO</small></div></div></article>`).join('')}</div>${projectRecords.length?'':'<div class="card empty-view"><h2>Chưa có dự án</h2><p>Thêm dự án đầu tiên để bắt đầu lập kế hoạch nguồn lực.</p><button class="primary-btn" data-add-project>＋ Thêm dự án</button></div>'}`}
