 const addExperience=document.querySelector('#addExperienceBtn');if(addExperience)addExperience.onclick=()=>{const project=prompt('Tên dự án kinh nghiệm');if(!project)return;experienceRecords.unshift({id:`KN-${Date.now().toString().slice(-4)}`,project,type:'Công nghiệp',period:'2026',investor:'Chưa cập nhật',value:'0 tỷ',person:people[0]?.name||'Chưa gán',role:'Thành viên'});render('competency');showToast('Đã thêm kinh nghiệm dự án')};
