 document.querySelectorAll('[data-delete-experience]').forEach(b=>b.onclick=()=>{const x=experienceRecords.find(e=>e.id===b.dataset.deleteExperience);if(!x||!confirm(`Xóa kinh nghiệm ${x.project}?`))return;experienceRecords.splice(experienceRecords.indexOf(x),1);render('competency');showToast('Đã xóa kinh nghiệm')});
