function openPersonMenu(button){document.querySelectorAll('.person-menu').forEach(x=>x.remove());const p=people.find(x=>x.code===button.dataset.person);const menu=document.createElement('div');menu.className='person-menu';menu.innerHTML=`<button data-action="project">Phân công dự án</button><button data-action="transfer">Điều chuyển phòng ban</button><button data-action="lock">Tạm khóa tài khoản</button><button data-action="leave">Đánh dấu nghỉ việc</button><button data-action="delete" class="danger-text">Xóa khỏi phòng ban</button>`;button.parentElement.style.position='relative';button.parentElement.append(menu);menu.querySelectorAll('button').forEach(x=>x.onclick=()=>{if(x.dataset.action==='delete'){if(!confirm(`Xóa ${p.name} khỏi phòng ban? Hệ thống sẽ lưu người thao tác, thời gian và lý do thay đổi.`))return;const index=people.findIndex(v=>v.code===p.code);if(index>=0)people.splice(index,1);const competencyIndex=competencyPeople.findIndex(v=>v.id===p.code);if(competencyIndex>=0)competencyPeople.splice(competencyIndex,1);render('people');showToast(`Đã xóa ${p.name} khỏi phòng ban và đồng bộ hồ sơ năng lực`);return}const labels={project:'Đã mở phân công dự án',transfer:'Đã tạo đề nghị điều chuyển',lock:'Đã tạm khóa tài khoản',leave:'Đã ghi nhận trạng thái nghỉ việc'};showToast(`${labels[x.dataset.action]} · ${p.name} · Lịch sử đã được lưu`);menu.remove()})}
function openEmployeeEditor(code){const p=people.find(x=>x.code===code);if(!p)return;const form=document.querySelector('#employeeForm');form.dataset.editCode=code;form.querySelector('h2').textContent='Chỉnh sửa nhân sự';['code','name','email','phone','position','role','department','workload'].forEach(k=>{if(form.elements[k])form.elements[k].value=p[k]??''});const d=(p.start||'').split('/');form.elements.startDate.value=d.length===3?`${d[2]}-${d[1]}-${d[0]}`:'';form.elements.code.readOnly=true;employeeDialog.showModal()}
function openProgressDialog(){const sel=document.querySelector('#progressTaskSelect');sel.innerHTML=tasks.filter(t=>t.status!=='Hoàn thành').map(t=>`<option value="${t.id}">${t.id} · ${t.title}</option>`).join('');progressDialog.showModal()}
function openTaskDialog(){const form=document.querySelector('#taskForm');form.elements.project.innerHTML=projectRecords.map(p=>`<option value="${p.name}">${p.name}</option>`).join('');form.elements.assignee.innerHTML=people.filter(p=>p.status==='Đang làm việc').map(p=>`<option value="${p.name}">${p.name} · ${p.position}</option>`).join('');dialog.showModal()}
function openProjectEditor(code,returnView='projects'){const form=document.querySelector('#projectForm'),members=form.elements.members;form.reset();members.innerHTML=people.map(p=>`<option value="${p.code}">${p.name} · ${p.position}</option>`).join('');projectDialog.dataset.returnView=returnView;if(code){const p=projectRecords.find(x=>x.code===code);form.dataset.editCode=code;form.querySelector('h2').textContent='Chỉnh sửa dự án';['code','name','type','investor','value','status','manager'].forEach(k=>{if(form.elements[k])form.elements[k].value=p[k]??''});form.elements.start.value=p.startISO||'';form.elements.due.value=p.dueISO||'';[...members.options].forEach(o=>o.selected=(p.assignees||[]).includes(o.value));form.elements.code.readOnly=true}else{delete form.dataset.editCode;form.querySelector('h2').textContent='Thêm dự án mới';form.elements.code.readOnly=false}projectDialog.showModal()}
function openApprovalEditor(){const form=document.querySelector('#approvalForm'),taskSelect=document.querySelector('#approvalTaskSelect'),memberSelect=document.querySelector('#approvalMemberSelect');form.reset();taskSelect.innerHTML=tasks.map(t=>`<option value="${t.id}">${t.id} · ${safeText(t.title)}</option>`).join('');memberSelect.innerHTML=people.map(p=>`<option value="${p.code}">${safeText(p.name)} · ${safeText(p.position)}</option>`).join('');const syncMember=()=>{const task=tasks.find(t=>t.id===taskSelect.value),person=people.find(p=>p.initials===task?.assignee);if(person)memberSelect.value=person.code};taskSelect.onchange=syncMember;syncMember();approvalDialog.showModal()}
function showWorklogDetail(index){const w=worklogs[index];if(!w)return;const taskId=w.task.split(' · ')[0],task=tasks.find(t=>t.id===taskId),completed=Math.max(0,w.after-w.before);document.querySelector('#reportDetailContent').innerHTML=`<div class="report-detail-hero"><div><span>${safeText(taskId)}</span><h3>${safeText(task?.title||w.task)}</h3><p>${safeText(w.user)} · ${safeText(w.time)} · ${safeText(w.status)}</p></div><strong>+${completed}%<small>khối lượng kỳ này</small></strong></div><div class="report-detail-grid"><div><span>Tiến độ trước</span><b>${w.before}%</b></div><div><span>Tiến độ sau</span><b>${w.after}%</b></div><div><span>Giờ thực hiện</span><b>${w.hours} giờ</b></div><div><span>Còn lại</span><b>${Math.max(0,100-w.after)}%</b></div></div><div class="detail-progress"><div><span>Khối lượng lũy kế</span><b>${w.after}%</b></div><div class="progress"><i style="width:${w.after}%"></i></div></div><section class="report-detail-section"><h4>Khối lượng công việc đã thực hiện</h4><p>${safeText(w.done)}</p></section><section class="report-detail-section ${w.blocker&&w.blocker!=='Không'?'has-warning':''}"><h4>Khó khăn, vướng mắc</h4><p>${safeText(w.blocker||'Không có vướng mắc')}</p></section>${w.support?`<section class="report-detail-section"><h4>Đề xuất hỗ trợ</h4><p>${safeText(w.support)}</p></section>`:''}${w.remaining?`<section class="report-detail-section"><h4>Khối lượng còn lại</h4><p>${safeText(w.remaining)}</p></section>`:''}${w.evidence?`<section class="report-detail-section"><h4>File minh chứng</h4><p>▤ ${safeText(w.evidence)}</p></section>`:''}`;reportDetailDialog.showModal()}
function orgDescendantIds(id,result=[]){projectOrgNodes.filter(n=>n.parentId===id).forEach(n=>{result.push(n.id);orgDescendantIds(n.id,result)});return result}
function openOrgNodeEditor(id=null,parentId=null,presetRole=''){const form=document.querySelector('#orgNodeForm'),node=id?projectOrgNodes.find(n=>n.id===id):null,nodes=projectOrgNodes.filter(n=>n.projectCode===activeOrgProjectCode),blocked=new Set(id?[id,...orgDescendantIds(id,[])]:[]);form.reset();form.elements.nodeId.value=node?.id||'';form.elements.role.value=node?.role||presetRole;form.elements.group.value=node?.group||'Ban chỉ huy';document.querySelector('#orgEmployeeSelect').innerHTML=`<option value="">— Chưa bổ nhiệm —</option>${people.filter(p=>p.status==='Đang làm việc').map(p=>`<option value="${p.code}">${safeText(p.name)} · ${safeText(p.position)} · Tải ${p.workload}%</option>`).join('')}`;form.elements.employeeCode.value=node?.employeeCode||'';document.querySelector('#orgParentSelect').innerHTML=`<option value="">— Vị trí gốc —</option>${nodes.filter(n=>!blocked.has(n.id)).map(n=>`<option value="${n.id}">${safeText(n.role)}</option>`).join('')}`;form.elements.parentId.value=node?.parentId||parentId||'';form.querySelector('h2').textContent=node?'Chỉnh sửa vị trí':'Thêm vị trí';orgNodeDialog.showModal()}
function refreshOrgPanel(){const panel=document.querySelector('[data-panel="org"]');if(!panel)return;panel.innerHTML=projectOrgEditor();wireOrgInteractions()}
function wireOrgInteractions(){const panel=document.querySelector('[data-panel="org"]');if(!panel)return;panel.querySelectorAll('[data-org-add-root]').forEach(b=>b.onclick=()=>openOrgNodeEditor());panel.querySelectorAll('[data-org-add-child]').forEach(b=>b.onclick=()=>openOrgNodeEditor(null,b.dataset.orgAddChild));panel.querySelectorAll('[data-org-edit]').forEach(b=>b.onclick=()=>openOrgNodeEditor(b.dataset.orgEdit));panel.querySelectorAll('[data-org-template]').forEach(b=>b.onclick=()=>openOrgNodeEditor(null,null,b.dataset.orgTemplate));panel.querySelectorAll('[data-org-delete]').forEach(b=>b.onclick=()=>{const node=projectOrgNodes.find(n=>n.id===b.dataset.orgDelete);if(!node)return;const ids=[node.id,...orgDescendantIds(node.id,[])];if(!confirm(`Xóa vị trí “${node.role}” và ${ids.length-1} vị trí trực thuộc?`))return;for(let i=projectOrgNodes.length-1;i>=0;i--)if(ids.includes(projectOrgNodes[i].id))projectOrgNodes.splice(i,1);refreshOrgPanel();showToast(`Đã xóa ${ids.length} vị trí khỏi sơ đồ`)});const save=panel.querySelector('#orgSaveBtn');if(save)save.onclick=()=>showToast('Đã lưu cấu trúc tổ chức dự án');const full=panel.querySelector('#orgDesignerFullscreen');if(full)full.onclick=()=>{const designer=panel.querySelector('.org-designer');designer.classList.toggle('org-designer-fullscreen');full.textContent=designer.classList.contains('org-designer-fullscreen')?'× Thu nhỏ':'⛶ Toàn màn hình'}}
function showToast(msg){toast.textContent=msg;toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),2600)}
document.querySelectorAll('[data-dialog-close]').forEach(button=>button.addEventListener('click',()=>{const modal=button.closest('dialog');if(modal?.open)modal.close('cancel')}));
document.querySelectorAll('.nav-item[data-view]').forEach(b=>b.onclick=()=>render(b.dataset.view));document.querySelector('#newTaskBtn').onclick=()=>openTaskDialog();document.querySelector('#menuBtn').onclick=()=>document.querySelector('#sidebar').classList.toggle('open');document.querySelector('#themeBtn').onclick=()=>{document.body.classList.toggle('dark');localStorage.setItem('workpilot-theme',document.body.classList.contains('dark')?'dark':'light')};
document.querySelector('#taskForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),person=people.find(p=>p.name===f.get('assignee'));tasks.unshift({id:`TSK-${1043+tasks.length}`,title:f.get('title'),project:f.get('project'),status:'Chưa bắt đầu',priority:f.get('priority'),due:new Date(f.get('due')).toLocaleDateString('vi-VN'),progress:0,assignee:person?.initials||people[0]?.initials||'NA'});dialog.close();e.currentTarget.reset();render('mytasks');showToast('Đã tạo và giao công việc mới')});
document.querySelector('#employeeForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),name=f.get('name'),initials=name.split(' ').slice(-2).map(x=>x[0]).join('').toUpperCase();if(form.dataset.editCode){const p=people.find(x=>x.code===form.dataset.editCode);Object.assign(p,{name,initials,position:f.get('position'),role:f.get('role'),department:f.get('department'),email:f.get('email'),phone:f.get('phone'),workload:+f.get('workload')});const cp=competencyPeople.find(x=>x.id===p.code);if(cp)Object.assign(cp,{name:p.name,initials:p.initials,title:p.position,dept:p.department,load:p.workload,kpi:p.kpi});delete form.dataset.editCode;form.elements.code.readOnly=false;form.querySelector('h2').textContent='Thêm nhân sự mới';employeeDialog.close();form.reset();render('people');showToast(`Đã cập nhật ${name} và đồng bộ Năng lực dự án`);return}const newPerson={code:f.get('code'),name,initials,position:f.get('position'),role:f.get('role'),department:f.get('department'),email:f.get('email'),phone:f.get('phone'),start:new Date(f.get('startDate')).toLocaleDateString('vi-VN'),status:'Đang làm việc',tasks:0,completion:0,overdue:0,kpi:0,workload:+f.get('workload')};people.unshift(newPerson);competencyPeople.unshift({id:newPerson.code,name:newPerson.name,initials:newPerson.initials,title:newPerson.position,dept:newPerson.department,years:0,load:newPerson.workload,kpi:0,skills:[0,0,0,0,0],cert:'Chưa cập nhật',certState:'missing',projects:0});employeeDialog.close();form.reset();render('people');showToast(`Đã thêm ${name} và đồng bộ Năng lực dự án`)});
document.querySelector('#projectForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),name=f.get('name'),code=f.get('code'),startISO=f.get('start'),dueISO=f.get('due'),assignees=[...form.elements.members.selectedOptions].map(o=>o.value),data={code,name,type:f.get('type'),investor:f.get('investor'),desc:`${f.get('type')} · ${f.get('investor')}`,value:+f.get('value'),startISO,dueISO,start:new Date(startISO).toLocaleDateString('vi-VN'),due:new Date(dueISO).toLocaleDateString('vi-VN'),manager:f.get('manager'),status:f.get('status'),assignees,members:assignees.length};if(form.dataset.editCode){const p=projectRecords.find(x=>x.code===form.dataset.editCode);Object.assign(p,data);delete form.dataset.editCode;showToast(`Đã cập nhật dự án ${name}`)}else{projectRecords.unshift({...data,progress:0,alerts:0});showToast(`Đã thêm dự án ${name}`)}const returnView=projectDialog.dataset.returnView||'projects';projectDialog.close();form.reset();form.elements.code.readOnly=false;render(returnView)});
document.querySelector('#approvalForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),task=tasks.find(t=>t.id===f.get('task')),person=people.find(p=>p.code===f.get('member')),type=f.get('type');if(!task||!person)return;approvalRecords.unshift({id:`PD-${Date.now().toString().slice(-5)}`,icon:type.includes('chi phí')?'₫':type.includes('tài liệu')?'▤':'✓',title:f.get('title'),project:task.project,member:person.name,value:f.get('value')||type,status:'Chờ phê duyệt',description:f.get('description'),taskId:task.id});approvalDialog.close();form.reset();render('approvals');showToast(`Đã gửi yêu cầu phê duyệt cho ${task.id}`)});
document.querySelector('#orgNodeForm').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,f=new FormData(form),id=f.get('nodeId'),data={projectCode:activeOrgProjectCode,parentId:f.get('parentId')||null,role:f.get('role'),employeeCode:f.get('employeeCode')||'',group:f.get('group')};if(id){const node=projectOrgNodes.find(n=>n.id===id);if(node)Object.assign(node,data)}else{projectOrgNodes.push({id:`ORG-${Date.now().toString().slice(-6)}`,...data})}orgNodeDialog.close();form.reset();refreshOrgPanel();showToast(id?'Đã cập nhật vị trí trong sơ đồ':'Đã thêm vị trí vào sơ đồ')});
document.querySelector('#progressForm').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),t=tasks.find(x=>x.id===f.get('task')),before=t?.progress||0,after=+f.get('progress'),evidence=f.get('evidence');if(t)t.progress=after;worklogs.unshift({user:'Quản trị GR',task:`${t.id} · ${t.title}`,before,after,hours:+f.get('hours'),done:f.get('done'),blocker:f.get('blocker')||'Không',support:f.get('support')||'',remaining:f.get('remaining')||'',evidence:evidence?.name||'',time:'Vừa xong',status:'Chờ duyệt'});progressDialog.close();e.currentTarget.reset();render('progressreports');showToast(`Đã ghi work log: ${before}% → ${after}%`)});
document.querySelector('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'){const q=e.currentTarget.value.trim().toLowerCase(),task=tasks.find(t=>t.title.toLowerCase().includes(q)||t.id.toLowerCase().includes(q)),project=projectRecords.find(p=>p.name.toLowerCase().includes(q)||p.code.toLowerCase().includes(q)),person=people.find(p=>p.name.toLowerCase().includes(q)||p.code.toLowerCase().includes(q));if(task){render('mytasks');showToast(`Đã tìm thấy ${task.id}`)}else if(project){render('projects');showToast(`Đã tìm thấy dự án ${project.name}`)}else if(person){render('people');showToast(`Đã tìm thấy ${person.name}`)}else showToast('Không tìm thấy công việc, dự án hoặc nhân sự phù hợp')}});if(localStorage.getItem('workpilot-theme')==='dark')document.body.classList.add('dark');render(location.hash.slice(1)||'dashboard');

